/**
 * Ed25519 Key Utilities
 * Normalizes cryptographic keys between raw PEM and base64-encoded PEM representations.
 */

/**
 * Normalizes an Ed25519 public or private key string.
 *
 * Handles:
 * 1. Raw PEM strings (with or without literal \n escapes from .env files)
 * 2. Base64-encoded PEM strings (as generated by scripts/development/gen-secrets.mjs)
 * 3. Enclosing quotes and whitespace
 *
 * Returns clean PEM string or null if input is empty or invalid.
 */
export function normalizeEd25519Key(raw: string | undefined | null): string | null {
  if (!raw) return null;
  let str = raw.trim();

  // Strip enclosing single or double quotes
  if (
    (str.startsWith('"') && str.endsWith('"')) ||
    (str.startsWith("'") && str.endsWith("'"))
  ) {
    str = str.slice(1, -1).trim();
  }

  // Handle literal escaped newlines ("\n") often present when pasting multiline PEM into single-line env vars
  if (str.includes('\\n')) {
    str = str.replace(/\\n/g, '\n');
  }

  // If not starting with PEM header, attempt base64 decode
  if (!str.startsWith('-----BEGIN')) {
    try {
      const decoded = Buffer.from(str, 'base64').toString('utf8').trim();
      if (decoded.includes('-----BEGIN')) {
        str = decoded;
      }
    } catch {
      // Ignore base64 decoding failure and let downstream crypto parsing report the error
    }
  }

  return str;
}

